CREATE TABLE IF NOT EXISTS property_leads(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),listing_id UUID NOT NULL REFERENCES property_listings(id) ON DELETE CASCADE,property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,buyer_id UUID NOT NULL REFERENCES users(id),status TEXT NOT NULL CHECK(status IN ('NEW','CONTACTED','QUALIFIED','VIEWING_REQUESTED','VIEWED','OFFERED','CLOSED','DECLINED')),message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS property_viewings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),lead_id UUID NOT NULL REFERENCES property_leads(id) ON DELETE CASCADE,listing_id UUID NOT NULL REFERENCES property_listings(id) ON DELETE CASCADE,property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,buyer_id UUID NOT NULL REFERENCES users(id),requested_for TIMESTAMPTZ NOT NULL,status TEXT NOT NULL CHECK(status IN ('REQUESTED','CONFIRMED','COMPLETED','CANCELLED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS property_offers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),lead_id UUID NOT NULL REFERENCES property_leads(id) ON DELETE CASCADE,listing_id UUID NOT NULL REFERENCES property_listings(id) ON DELETE CASCADE,property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,buyer_id UUID NOT NULL REFERENCES users(id),amount_cents BIGINT NOT NULL CHECK(amount_cents>0),conditions JSONB NOT NULL DEFAULT '[]'::jsonb,status TEXT NOT NULL CHECK(status IN ('SUBMITTED','UNDER_REVIEW','ACCEPTED','REJECTED','WITHDRAWN')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS property_leads_buyer_idx ON property_leads(buyer_id); CREATE INDEX IF NOT EXISTS property_leads_listing_idx ON property_leads(listing_id); CREATE INDEX IF NOT EXISTS property_viewings_listing_idx ON property_viewings(listing_id); CREATE INDEX IF NOT EXISTS property_offers_listing_idx ON property_offers(listing_id);
